-- Режим проверки QA доезжает до промптов агента — шаги 445/447/516/451 (WF57).
--
-- `task_agent_qa_mode` читает `qa_mode` из metadata задачи и кладёт в wf_vars две
-- переменные: `subtask_qa_mode` (`lite`/`full` — видно и человеку, и агенту) и
-- `subtask_qa_full` (`yes`/пусто). `%if%` в движке проверяет только непустоту
-- (`ai_workflow_variable_truthy`), поэтому `lite` как условие был бы истинным —
-- развилка висит на `subtask_qa_full`.
--
-- Без этого шага 57 переменную принимает, но в 33 своих промптах не использует ни
-- одного раза: режим выбирается ни на что не влияя. Правки дают развилку в наборе
-- проверок (445), в прогоне (447), в проверке каждой цели по отдельности (516) и в
-- вердикте (451), где непрогнанные в Lite тесты не должны становиться дефектом.
-- Запускаемые пункты — браузер, запрос к API, тесты — сворачиваются в один читаемый
-- блок: в Lite агент проверяет код, спецификацию и документацию. Вложенных `%if%`
-- нет — регулярка движка (`WORKFLOW_IF_BLOCK_RE`) матчит только внутренние блоки.
--
-- Переводы строк записаны как `\\n`: в `metadata` лежит JSON, а MySQL-литерал `'\n'`
-- — настоящий перевод строки, который внутри JSON-строки делает её невалидной.
--
-- Признак «уже применено» — фраза из собственной правки каждого оператора, не общее
-- на всех слово: шаг 447 правят три оператора, и общий признак второго накрыл бы
-- третий — оборванный круг оставил бы промпт с половиной развилки, которую повторный
-- прогон уже не допишет (урок в `20260830171000_wf56_docs_check.sql`).

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, 'Нашёл дефект — это замечание разработчику, а не повод исправить самому.', 'Нашёл дефект — это замечание разработчику, а не повод исправить самому.\\n\\n=== РЕЖИМ ПРОВЕРКИ: %subtask_qa_mode% ===\\nРежим выбирает человек на странице задачи, рядом с кнопкой «лог»; всего их два.\\n%if subtask_qa_full%Full: кроме разбора — прогон всего, что можно прогнать: существующие тесты\\n  проекта, живой браузер, запросы к API. Так он расписан ниже, в наборе проверок.\\n%else%Lite (он же по умолчанию): проверяются код, соответствие спецификации и\\n  документация. Ничего не запускаем — ни тестов, ни прочих прогонов; в наборе\\n  проверок их нет, и отсутствующий прогон — не замечание.\\n%endif%')
 WHERE `id` = 445 AND `workflow_id` = 57
   AND `metadata` LIKE 'Нашёл дефект — это замечание разработчику, а не повод исправить самому.'
   AND `metadata` NOT LIKE '%Режим выбирает человек на странице задачи%';

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, '3. Собери набор проверок, применимый именно здесь. Для каждой цели подзадачи\\n   заранее реши, чем ты воспроизведёшь поведение: браузером, запросом к API или\\n   существующим тестом из tests/. Синтаксис и grep — это довесок, а не проверка.\\n', '3. Собери набор проверок, применимый именно здесь.\\n%if subtask_qa_full%   Для каждой цели подзадачи заранее реши, чем воспроизведёшь поведение:\\n   браузером, запросом к API или существующим тестом из tests/. Синтаксис и grep\\n   — довесок, а не проверка.\\n%else%   Режим Lite: проверки читаемые — код подзадачи, `.task-spec.md` как спецификация\\n   и документация. Воспроизводить поведение не нужно, прогонов в наборе не\\n   планируется; Синтаксис и grep — и подавно довесок.\\n%endif%')
 WHERE `id` = 445 AND `workflow_id` = 57
   AND `metadata` LIKE '3. Собери набор проверок, применимый именно здесь. Для каждой цели подзадачи\\n   заранее реши, чем ты воспроизведёшь поведение: браузером, запросом к API или\\n   существующим тестом из tests/. Синтаксис и grep — это довесок, а не проверка.\\n'
   AND `metadata` NOT LIKE '%Режим Lite: проверки читаемые%';

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, '- Страница админки или её JS — открывай живым браузером: playwright, headless\\n  chromium, вход QA-учёткой; образец логина и работы с селекторами —\\n  tests/test_team_task_pages.py. Кликаешь тот самый элемент и смотришь результат\\n  БЕЗ перезагрузки страницы. Состояние после перезагрузки — отдельная проверка, ею\\n  клик не заменяется.\\n- API — реальный запрос к запущенному серверу: код ответа и тело.\\n- Фоновая логика — прогон существующих тестов проекта из tests/. Адрес сервера\\n  сюита берёт из переменной окружения, поэтому гони её на сервер ветки:\\n  BASE_URL=%subtask_server_url% .venv/bin/python3 -m pytest tests/<файл> -q\\n', '%if subtask_qa_full%- Страница админки или её JS — открывай живым браузером: playwright, headless\\n  chromium, вход QA-учёткой; образец логина и работы с селекторами —\\n  tests/test_team_task_pages.py. Кликаешь тот самый элемент и смотришь результат\\n  БЕЗ перезагрузки страницы. Состояние после перезагрузки — отдельная проверка, ею\\n  клик не заменяется.\\n- API — реальный запрос к запущенному серверу: код ответа и тело.\\n- Фоновая логика — прогон существующих тестов проекта из tests/. Адрес сервера\\n  сюита берёт из переменной окружения, поэтому гони её на сервер ветки:\\n  BASE_URL=%subtask_server_url% .venv/bin/python3 -m pytest tests/<файл> -q\\n%else%- Режим Lite: ничего не прогоняем — ни браузером, ни запросами к API, ни\\n  тестами. Проверкой считается чтение: код подзадачи, `.task-spec.md` как\\n  спецификация, `CLAUDE.md` и `.claude/docs/`. Команд в отчёте не ставь —\\n  они появляются только в режиме Full.\\n%endif%')
 WHERE `id` = 447 AND `workflow_id` = 57
   AND `metadata` LIKE '- Страница админки или её JS — открывай живым браузером: playwright, headless\\n  chromium, вход QA-учёткой; образец логина и работы с селекторами —\\n  tests/test_team_task_pages.py. Кликаешь тот самый элемент и смотришь результат\\n  БЕЗ перезагрузки страницы. Состояние после перезагрузки — отдельная проверка, ею\\n  клик не заменяется.\\n- API — реальный запрос к запущенному серверу: код ответа и тело.\\n- Фоновая логика — прогон существующих тестов проекта из tests/. Адрес сервера\\n  сюита берёт из переменной окружения, поэтому гони её на сервер ветки:\\n  BASE_URL=%subtask_server_url% .venv/bin/python3 -m pytest tests/<файл> -q\\n'
   AND `metadata` NOT LIKE '%Команд в отчёте не ставь%';

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, '- Твоё дело на этом ходе — общая приёмка: изменения отвечают плану, лишнего в них\\n  нет, существующий набор тестов проходит, побочных эффектов у соседнего поведения\\n  не видно.', '- Твоё дело на этом ходе — общая приёмка: изменения отвечают плану, лишнего в них\\n%if subtask_qa_full%  нет, существующий набор тестов проходит, побочных эффектов у соседнего\\n  поведения не видно.\\n%else%  нет, документация не расходится с сделанным, побочных эффектов у соседнего\\n  поведения не видно. Прогон тестов здесь не ожидается — он в режиме Full.\\n%endif%')
 WHERE `id` = 447 AND `workflow_id` = 57
   AND `metadata` LIKE '- Твоё дело на этом ходе — общая приёмка: изменения отвечают плану, лишнего в них\\n  нет, существующий набор тестов проходит, побочных эффектов у соседнего поведения\\n  не видно.'
   AND `metadata` NOT LIKE '%документация не расходится с сделанным%';

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, '- Гоняешь существующий набор тестов проекта. Новые тесты под этот прогон не\\n  пишешь и произвольный сгенерированный код не исполняешь. Разовый скрипт\\n  браузерной проверки — исключение: он ничего не меняет и в репозиторий не идёт.\\n', '%if subtask_qa_full%- Гоняешь существующий набор тестов проекта. Новые тесты под этот прогон не\\n  пишешь и произвольный сгенерированный код не исполняешь. Разовый скрипт\\n  браузерной проверки — исключение: он ничего не меняет и в репозиторий не идёт.\\n%else%- Режим Lite: ничего не запускаешь — ни сюиты из tests/, ни браузера, ни скриптов.\\n  Отчёт строится на прочитанном: код, `.task-spec.md`, `CLAUDE.md`, `.claude/docs/`.\\n%endif%')
 WHERE `id` = 447 AND `workflow_id` = 57
   AND `metadata` LIKE '- Гоняешь существующий набор тестов проекта. Новые тесты под этот прогон не\\n  пишешь и произвольный сгенерированный код не исполняешь. Разовый скрипт\\n  браузерной проверки — исключение: он ничего не меняет и в репозиторий не идёт.\\n'
   AND `metadata` NOT LIKE '%ни сюиты из tests/, ни браузера%';

