   AND `metadata` NOT LIKE '%По цели ответ тот же%';

UPDATE `agent_workflow_step`
   SET `metadata` = REPLACE(`metadata`, '3. Ничего рядом не сломано и правила проекта не нарушены?', '3. Ничего рядом не сломано и правила проекта не нарушены?\\n%if !subtask_qa_full%   Режим Lite: непрогнанные тесты здесь не порок. Ничего и не запускалось по\\n   условиям прогона — это не дефект и не повод для qa_ok=no. Суди по коду,\\n   спецификации и документации.\\n%endif%')
 WHERE `id` = 451 AND `workflow_id` = 57
   AND `metadata` LIKE '3. Ничего рядом не сломано и правила проекта не нарушены?'
   AND `metadata` NOT LIKE '%непрогнанные тесты здесь не порок%';
